<div class="mb-8"><p class="text-[10px] font-bold uppercase tracking-[.2em] text-[#687158]"><?= __('Offers for you') ?></p><h1 class="mt-2 text-3xl font-medium"><?= __('Coupons') ?></h1><p class="mt-2 text-sm text-[#77796f]"><?= __('Apply an available offer at checkout and make your next order more rewarding.') ?></p></div>
<section class="mb-6 rounded-2xl bg-[#252820] p-6 text-[#f4f3ed]"><div class="flex flex-wrap items-end justify-between gap-5"><div><p class="text-[10px] font-bold uppercase tracking-[.18em] text-[#b6c09e]"><?= __('Have a code?') ?></p><h2 class="mt-2 text-xl font-medium"><?= __('Apply coupon') ?></h2></div><form id="coupon-form" class="flex w-full max-w-md gap-2"><input name="code" class="min-w-0 flex-1 rounded-xl border border-white/15 bg-white/10 px-4 py-3 text-sm uppercase tracking-[.12em] text-white outline-none placeholder:text-[#b9bcb2]" placeholder="<?= e(__('Coupon code')) ?>" required><button class="rounded-xl bg-[#b6c09e] px-4 py-3 text-xs font-semibold text-[#252820]" type="submit"><?= __('Apply') ?></button></form></div><?php if(!empty($appliedCoupon)): ?><p class="mt-4 text-xs text-[#b6c09e]"><?= __('Currently applied') ?>: <strong><?= e($appliedCoupon['code']) ?></strong></p><?php endif; ?></section>
<div class="grid gap-5 md:grid-cols-2"><?php if(!$coupons): ?><div class="rounded-2xl border border-dashed border-[#d6d6cd] p-8 text-sm text-[#77796f]"><?= __('There are no active coupons available right now.') ?></div><?php endif; ?><?php foreach($coupons as $coupon): ?><article class="relative overflow-hidden rounded-2xl border border-[#e5e5dd] bg-[#fbfbf7] p-6"><div class="absolute -right-8 -top-8 h-24 w-24 rounded-full border-[14px] border-[#e9ede0]"></div><div class="relative"><div class="flex items-start justify-between gap-4"><div><p class="text-[10px] font-bold uppercase tracking-[.18em] text-[#687158]"><?= __('Noir offer') ?></p><h2 class="mt-3 text-2xl font-medium"><?php if($coupon['discount_type']==='percent'): ?><?= e(rtrim(rtrim(number_format((float)$coupon['discount_value'],2), '0'), '.')) ?>% <?= __('off') ?><?php elseif($coupon['discount_type']==='free_shipping'): ?><?= __('Free delivery') ?><?php else: ?><?= format_currency((float)$coupon['discount_value']) ?> <?= __('off') ?><?php endif; ?></h2></div><i data-lucide="ticket-percent" class="h-6 w-6 text-[#687158]"></i></div><p class="mt-3 max-w-sm text-sm leading-6 text-[#77796f]"><?= e($coupon['description']) ?></p><?php if((float)$coupon['minimum_order_amount']>0): ?><p class="mt-3 text-xs text-[#92948a]"><?= __('Minimum order') ?>: <?= format_currency((float)$coupon['minimum_order_amount']) ?></p><?php endif; ?><div class="mt-6 flex items-center justify-between gap-3 border-t border-[#e8e8e0] pt-4"><code class="rounded-lg bg-[#eef0e7] px-3 py-2 text-xs font-semibold tracking-[.16em] text-[#687158]"><?= e($coupon['code']) ?></code><button class="copy-coupon text-xs font-semibold text-[#687158] underline" data-code="<?= e($coupon['code']) ?>"><?= __('Copy code') ?></button></div><?php if($coupon['expires_at']): ?><p class="mt-3 text-[10px] text-[#92948a]"><?= __('Expires') ?> <?= e(date('d M Y', strtotime($coupon['expires_at']))) ?></p><?php else: ?><p class="mt-3 text-[10px] text-[#92948a]"><?= __('No expiry date') ?></p><?php endif; ?></div></article><?php endforeach; ?></div>
<script>$('#coupon-form').on('submit',function(e){e.preventDefault();$.post('<?= e(($base ?: '') . '/customer/ajax/coupon-apply') ?>',$(this).serialize()).done(function(r){customerToast(r.message||'Coupon applied.');setTimeout(()=>location.reload(),400)}).fail(function(xhr){customerToast((xhr.responseJSON||{}).message||'Unable to apply coupon.')})});$('.copy-coupon').on('click',function(){const code=$(this).data('code');navigator.clipboard?.writeText(code);customerToast(code+' copied to clipboard.')});</script>
